import { requestToken } from '@ecommerce/shared-library';
import { EmptyState, ErrorState, LoadingState } from '@ecommerce/shared-library/src/ui/StateViews';
import { dateInput, tokenHasAccountingPermission, tokenUserId } from './accountingSession';
import React, { useEffect, useMemo, useState } from 'react';
import {
  Alert, Box, Button, Card, CardContent, Chip, Dialog, DialogActions,
  DialogContent, DialogTitle, Divider, Grid, MenuItem, Paper, Stack, Tab, Table, TableBody,
  TableCell, TableContainer, TableHead, TableRow, Tabs, TextField, Typography,
} from '@mui/material';
import { AccountBalanceRounded, AssessmentRounded, DownloadRounded, ReceiptLongRounded } from '@mui/icons-material';
import axios from 'axios';
import { useLocation, useNavigate } from 'react-router-dom';
import { CartesianGrid, Legend, Line, LineChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts';
import { businessCurrency, displayRates, formatMoney } from '@ecommerce/shared-library';
import { PLACES_OF_SUPPLY, gstinProblem, isHsnCode, lastMonth, placeName, rateProblem, suggestedRate, toBase } from './accountingModel';

const api = axios.create(); // Same origin: nginx (containers) and the Vite dev proxy forward /api to the gateway.
api.interceptors.request.use((config) => {
  const token = requestToken((config.baseURL || '') + (config.url || ''));
  if (token) config.headers.Authorization = `Bearer ${token}`;
  return config;
});

type Row = Record<string, any>;
const money = (value: unknown, currency = businessCurrency()) => formatMoney(Number(value || 0), currency);
const dateValue = (value: unknown) => String(value || '').slice(0, 10);
const messageOf = (e: any): string => {
  const data = e?.response?.data;
  if (typeof data === 'string' && data.trim()) return data;
  if (data && typeof data === 'object') return String(data.message || data.error || data.detail || `Request failed (${e?.response?.status ?? 'error'})`);
  return e?.message || 'Request failed';
};
const a = '/api/accounting/admin';
function hasAccountingPermission(permission: string) {
  return tokenHasAccountingPermission(requestToken('/api/accounting/admin'), permission);
}
function currentAccountingUserId(): number | null {
  return tokenUserId(requestToken('/api/accounting/admin'));
}

function PageHeading({ title, detail, action }: { title: string; detail: string; action?: React.ReactNode }) {
  return <Stack direction={{ xs: 'column', sm: 'row' }} justifyContent="space-between" alignItems={{ xs: 'flex-start', sm: 'center' }} spacing={2} sx={{ mb: 3 }}>
    <Box><Typography variant="h4" fontWeight={800}>{title}</Typography><Typography color="text.secondary">{detail}</Typography></Box>{action}
  </Stack>;
}
function DataTable({ columns, rows, empty = 'No records found.' }: { columns: { key: string; label: string; render?: (row: Row) => React.ReactNode }[]; rows: Row[]; empty?: string }) {
  return <TableContainer component={Paper} variant="outlined"><Table size="small"><TableHead><TableRow>{columns.map(c => <TableCell key={c.key} sx={{ fontWeight: 800, whiteSpace: 'nowrap' }}>{c.label}</TableCell>)}</TableRow></TableHead>
    <TableBody>{rows.map((row, i) => <TableRow hover key={row.id || i}>{columns.map(c => <TableCell key={c.key}>{c.render ? c.render(row) : String(row[c.key] ?? '—')}</TableCell>)}</TableRow>)}
      {!rows.length && <TableRow><TableCell colSpan={columns.length} sx={{ borderBottom: 0, p: 2 }}><EmptyState compact title={empty} hint="Change the filters or the date range above to see more." /></TableCell></TableRow>}</TableBody></Table></TableContainer>;
}
function useLoad<T>(url: string, params?: Record<string, unknown>) {
  const [data, setData] = useState<T | null>(null); const [busy, setBusy] = useState(false); const [error, setError] = useState(''); const [refresh, setRefresh] = useState(0);
  useEffect(() => { let alive = true; setBusy(true); setError(''); api.get(url, { params }).then(r => { if (alive) setData(r.data); }).catch(e => { if (alive) setError(String(messageOf(e))); }).finally(() => { if (alive) setBusy(false); }); return () => { alive = false; }; }, [url, JSON.stringify(params), refresh]);
  return { data, busy, error, reload: () => setRefresh(v => v + 1) };
}
// Placeholder cards while loading, and a failure with a retry, instead of a bare spinner or a one-line alert.
function Feedback({ busy, error, onRetry }: { busy: boolean; error: string; onRetry?: () => void }) {
  return <>{busy && <LoadingState layout="cards" rows={4} label="Loading finance data" />}{error && <Box sx={{ mb: 2 }}><ErrorState message={error} onRetry={onRetry} /></Box>}</>;
}
// The currency the books are kept in (Accounting settings). Entries in another currency carry an exchange rate to it.
function useBaseCurrency(): string {
  const { data } = useLoad<Row>(`${a}/settings`);
  return String(data?.baseCurrency || businessCurrency());
}
async function download(url: string, params: Record<string, unknown>, filename: string) {
  const r = await api.get(url, { params, responseType: 'blob' });
  const u = URL.createObjectURL(r.data); const link = document.createElement('a'); link.href = u; link.download = filename; document.body.appendChild(link); link.click(); link.remove();
  setTimeout(() => URL.revokeObjectURL(u), 30000); // revoking at once can cancel the download in Chromium
}
// Currency and exchange rate fields for an entry; the rate is how many base units one unit of the entry currency is worth.
function CurrencyRateFields({ base, currency, rate, onCurrency, onRate, amount }: { base: string; currency: string; rate: string; onCurrency: (v: string) => void; onRate: (v: string) => void; amount?: number }) {
  const foreign = Boolean(currency) && currency !== base; const problem = foreign ? rateProblem(currency, base, rate) : '';
  return <Grid container spacing={2}>
    <Grid item xs={12} sm={foreign ? 4 : 6}><TextField fullWidth size="small" label="Currency" inputProps={{ maxLength: 3 }} value={currency} helperText={foreign ? `Books are kept in ${base}` : `Same as the books (${base})`}
      onChange={e => { const next = e.target.value.toUpperCase(); onCurrency(next); if (/^[A-Z]{3}$/.test(next)) onRate(suggestedRate(base, next, displayRates())); }} /></Grid>
    {foreign && <Grid item xs={12} sm={4}><TextField fullWidth size="small" label={`${base} per 1 ${currency}`} type="number" value={rate} error={Boolean(rate) && Boolean(problem)} helperText={problem || 'Use the rate on the transaction date, from your bank'} onChange={e => onRate(e.target.value)} /></Grid>}
    {foreign && amount !== undefined && !problem && <Grid item xs={12} sm={4}><TextField fullWidth size="small" label={`In ${base}`} value={money(toBase(amount, Number(rate)), base)} InputProps={{ readOnly: true }} /></Grid>}
  </Grid>;
}

export function FinanceOverviewPage() {
  const [from, setFrom] = useState(() => { const date = new Date(); date.setMonth(date.getMonth() - 5); date.setDate(1); return dateInput(date); });
  const [to, setTo] = useState(() => dateInput(new Date()));
  const params = useMemo(() => ({ startDate: from ? `${from}T00:00:00` : undefined, endDate: to ? `${to}T23:59:59` : undefined, currency: businessCurrency() }), [from, to]);
  const reportParams = useMemo(() => ({ startDate: from, endDate: to, currency: businessCurrency() }), [from, to]);
  const { data, busy, error, reload } = useLoad<Row>(`${a}/dashboard`, params);
  const { data: cashFlow } = useLoad<Row>(`${a}/reports/cash-flow`, reportParams);
  const { data: trendData } = useLoad<Row[]>(`${a}/reports/trends`, reportParams);
  const metrics = [
    ['Gross sales', data?.grossSales, 'Posted orders in the selected period'], ['Refunds', data?.totalRefunds, 'Posted refunds in the selected period'],
    ['Net cash flow', cashFlow?.netCashFlow, 'Cash account movement for the selected period'], ['Pending exposure', data?.failedOrPendingAmount, `${data?.failedOrPendingCount || 0} pending or failed entries`],
  ];
  return <Box><PageHeading title="Finance overview" detail="A working view of recorded ledger activity and reconciliation health." action={<Button onClick={reload} variant="outlined">Refresh</Button>} />
    <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2} sx={{ mb: 2 }}><TextField type="date" label="From" size="small" InputLabelProps={{ shrink: true }} value={from} onChange={e => setFrom(e.target.value)} /><TextField type="date" label="To" size="small" InputLabelProps={{ shrink: true }} value={to} onChange={e => setTo(e.target.value)} /><Chip icon={<AssessmentRounded />} label={`${data?.totalTransactionsCount || 0} transactions · ${data?.flaggedReconciliationCount || 0} flagged`} color={data?.flaggedReconciliationCount ? 'warning' : 'default'} variant="outlined" /></Stack>
    <Feedback busy={busy} error={error} onRetry={reload} />
    <Grid container spacing={2} sx={{ mb: 3 }}>{metrics.map(([label, value, help]) => <Grid item xs={12} sm={6} lg={3} key={String(label)}><Card variant="outlined"><CardContent><Typography color="text.secondary" variant="body2">{label}</Typography><Typography variant="h4" fontWeight={800} sx={{ my: 1 }}>{money(value)}</Typography><Typography variant="caption" color="text.secondary">{help}</Typography></CardContent></Card></Grid>)}</Grid>
    <Grid container spacing={2}><Grid item xs={12} lg={8}><Paper variant="outlined" sx={{ p: 2.5, height: '100%' }}><Typography variant="h6" fontWeight={800}>Sales and refund trend</Typography><Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>Monthly posted totals for the selected date range.</Typography><Box sx={{ width: '100%', height: 280 }}><ResponsiveContainer><LineChart data={Array.isArray(trendData) ? trendData : []} margin={{ top: 8, right: 12, bottom: 4, left: 0 }}><CartesianGrid stroke="#26324A" strokeDasharray="4 4"/><XAxis dataKey="month" tickFormatter={month => new Date(`${month}-01T00:00:00`).toLocaleDateString(undefined,{month:'short',year:'2-digit'})} stroke="#9AA6BD"/><YAxis tickFormatter={value => new Intl.NumberFormat(undefined,{notation:'compact'}).format(Number(value))} stroke="#9AA6BD"/><Tooltip formatter={value => money(value as number)} contentStyle={{background:'#131A2C',border:'1px solid #26324A',borderRadius:12}}/><Legend/><Line type="monotone" dataKey="revenue" name="Revenue" stroke="#45D6C1" strokeWidth={3} dot={false}/><Line type="monotone" dataKey="refunds" name="Refunds" stroke="#FF8D9A" strokeWidth={2} dot={false}/></LineChart></ResponsiveContainer></Box></Paper></Grid><Grid item xs={12} lg={4}><Paper variant="outlined" sx={{ p: 2.5, height: '100%' }}><Typography variant="h6" fontWeight={800} sx={{ mb: 2 }}>Reconciliation health</Typography><Stack direction="row" spacing={1} flexWrap="wrap"><Chip color={data?.failedOrPendingCount ? 'warning' : 'success'} variant={data?.failedOrPendingCount ? 'filled' : 'outlined'} label={`${data?.failedOrPendingCount || 0} pending / failed`} /><Chip color={data?.flaggedReconciliationCount ? 'error' : 'success'} variant={data?.flaggedReconciliationCount ? 'filled' : 'outlined'} label={`${data?.flaggedReconciliationCount || 0} flagged`} /></Stack><Typography variant="body2" color="text.secondary" sx={{ mt: 2 }}>{data?.disclaimer || 'Figures include recorded activity and may not reflect external statements until reconciled.'}</Typography><Divider sx={{my:2}}/><Typography variant="body2" color="text.secondary">Cash flow in the selected range</Typography><Typography variant="h5" fontWeight={800} sx={{mt:.5}}>{money(cashFlow?.netCashFlow)}</Typography><Stack spacing={1.2} sx={{ mt: 2 }}><Button href="/accounting/invoices" startIcon={<ReceiptLongRounded />} variant="contained">Create an invoice</Button><Button href="/accounting/journals" startIcon={<AccountBalanceRounded />} variant="outlined">Post a journal</Button><Button href="/accounting/reports" startIcon={<AssessmentRounded />} variant="outlined">Open financial reports</Button></Stack></Paper></Grid></Grid>
  </Box>;
}

export function InvoicesPage() {
  const [status, setStatus] = useState(''); const [term, setTerm] = useState(''); const [open, setOpen] = useState(false); const [saving, setSaving] = useState(false); const [error, setError] = useState(''); const [notice, setNotice] = useState('');
  const { data, busy, error: loadError, reload } = useLoad<Row>(`${a}/invoices`, { status: status || undefined, term: term || undefined }); const rows: Row[] = data?.items || [];
  const [editingInvoiceId, setEditingInvoiceId] = useState<number | null>(null); const [editingLineCount, setEditingLineCount] = useState(0);
  const [form, setForm] = useState({ userId: '', customerEmail: '', orderId: '', type: 'INVOICE', description: '', quantity: '1', unitPrice: '', taxRate: '0', dueDate: '', notes: '', customerName: '', customerGstin: '', placeOfSupply: '', hsnCode: '', currency: '', exchangeRate: '1', originalInvoiceNumber: '' });
  const startCreate = () => { setEditingInvoiceId(null); setEditingLineCount(0); setForm({ userId: '', customerEmail: '', orderId: '', type: 'INVOICE', description: '', quantity: '1', unitPrice: '', taxRate: '0', dueDate: '', notes: '', customerName: '', customerGstin: '', placeOfSupply: '', hsnCode: '', currency: '', exchangeRate: '1', originalInvoiceNumber: '' }); setError(''); setOpen(true); };
  const startEdit = async (row: Row) => { setError(''); try { const { data: full } = await api.get(`${a}/invoices/${row.id}`); const first = full.lines?.[0] || {}; setEditingInvoiceId(row.id); setEditingLineCount(full.lines?.length || 0); setForm({ userId: String(full.userId || ''), customerEmail: full.customerEmail || '', orderId: full.orderId ? String(full.orderId) : '', type: full.type || 'INVOICE', description: first.description || '', quantity: String(first.quantity ?? '1'), unitPrice: String(first.unitPrice ?? ''), taxRate: String(first.taxRate ?? '0'), dueDate: String(full.dueDate || '').slice(0, 10), notes: full.notes || '', customerName: full.customerName || '', customerGstin: full.customerGstin || '', placeOfSupply: full.placeOfSupply || '', hsnCode: first.hsnCode || '', currency: full.currency || '', exchangeRate: String(full.exchangeRate ?? '1'), originalInvoiceNumber: full.originalInvoiceNumber || '' }); setOpen(true); } catch (e) { setError(String(messageOf(e))); } };
  const save = async () => { setSaving(true); setError(''); try { const cur = form.currency || base; const payload: Row = { userId: Number(form.userId), customerEmail: form.customerEmail || undefined, orderId: form.orderId ? Number(form.orderId) : undefined, type: form.type, dueDate: form.dueDate || undefined, notes: form.notes || undefined, currency: cur, exchangeRate: cur === base ? undefined : Number(form.exchangeRate), customerName: form.customerName.trim() || null, customerGstin: form.customerGstin.trim() || null, placeOfSupply: form.customerGstin.trim() ? null : form.placeOfSupply || null, originalInvoiceNumber: form.type === 'CREDIT_NOTE' ? form.originalInvoiceNumber.trim() || null : null }; if (editingInvoiceId === null) { payload.idempotencyKey = crypto.randomUUID(); payload.lineItems = [{ description: form.description, quantity: Number(form.quantity), unitPrice: Number(form.unitPrice), taxRate: Number(form.taxRate), hsnCode: form.hsnCode.trim() || undefined }]; await api.post(`${a}/invoices`, payload); setNotice('Invoice saved as a draft.'); } else { if (editingLineCount <= 1) payload.lineItems = [{ description: form.description, quantity: Number(form.quantity), unitPrice: Number(form.unitPrice), taxRate: Number(form.taxRate), hsnCode: form.hsnCode.trim() || undefined }]; await api.put(`${a}/invoices/${editingInvoiceId}`, payload); setNotice('Draft invoice updated.'); } setOpen(false); setEditingInvoiceId(null); reload(); } catch (e) { setError(String(messageOf(e))); } finally { setSaving(false); } };
  const base = useBaseCurrency(); const formCurrency = form.currency || base; const gstinIssue = gstinProblem(form.customerGstin); const hsnIssue = form.hsnCode.trim() && !isHsnCode(form.hsnCode) ? 'HSN/SAC codes have 4, 6 or 8 digits.' : ''; const invoiceRateIssue = rateProblem(formCurrency, base, form.exchangeRate);
  const changeStatus = async (row: Row, next: string) => { try { await api.patch(`${a}/invoices/${row.id}/status`, { status: next }); setNotice(`Invoice ${row.invoiceNumber} updated.`); reload(); } catch (e) { setError(String(messageOf(e))); } };
  return <Box><PageHeading title="Invoices & credit notes" detail="Create drafts, issue invoices, and track paid or overdue balances." action={hasAccountingPermission("accounting:write") ? <Button variant="contained" onClick={startCreate}>New invoice</Button> : undefined} />
    <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1.5} sx={{ mb: 2 }}><TextField size="small" label="Search invoice, customer, order" value={term} onChange={e => setTerm(e.target.value)} /><TextField select size="small" label="Status" value={status} onChange={e => setStatus(e.target.value)} sx={{ minWidth: 160 }}><MenuItem value="">All statuses</MenuItem>{['DRAFT','ISSUED','PAID','OVERDUE','VOID'].map(x => <MenuItem value={x} key={x}>{x}</MenuItem>)}</TextField></Stack>
    <Feedback busy={busy} error={loadError || error} />{notice && <Alert severity="success" onClose={() => setNotice('')} sx={{ mb: 2 }}>{notice}</Alert>}
    <DataTable rows={rows} columns={[{ key: 'invoiceNumber', label: 'Invoice' }, { key: 'type', label: 'Type', render: r => <Chip size="small" label={r.type} /> }, { key: 'customerEmail', label: 'Customer', render: r => <Box>{r.customerName || r.customerEmail || '—'}{r.customerGstin && <Typography variant="caption" display="block" color="text.secondary">GSTIN {r.customerGstin}</Typography>}</Box> }, { key: 'orderId', label: 'Order' }, { key: 'totalAmount', label: 'Total', render: r => <Box>{money(r.totalAmount, r.currency)}{r.baseCurrency && r.baseCurrency !== r.currency && <Typography variant="caption" display="block" color="text.secondary">{money(r.baseTotalAmount, r.baseCurrency)}</Typography>}</Box> }, { key: 'placeOfSupply', label: 'Place of supply', render: r => r.placeOfSupply ? `${r.placeOfSupply} · ${placeName(r.placeOfSupply)}` : '—' }, { key: 'issueDate', label: 'Issue date', render: r => dateValue(r.issueDate) || '—' }, { key: 'dueDate', label: 'Due date', render: r => dateValue(r.dueDate) || '—' }, { key: 'status', label: 'Status', render: r => <TextField disabled={!hasAccountingPermission("accounting:approve")} select size="small" value={r.status} onChange={e => changeStatus(r, e.target.value)} sx={{ minWidth: 130 }}>{['DRAFT','ISSUED','PAID','OVERDUE','VOID'].map(x => <MenuItem value={x} key={x}>{x}</MenuItem>)}</TextField> }, { key: 'draft', label: 'Draft action', render: r => r.status === 'DRAFT' ? <Button size="small" onClick={() => void startEdit(r)}>Edit draft</Button> : '—' }, { key: 'print', label: 'Print', render: r => <Button size="small" onClick={async () => { try { const { data: full } = await api.get(`${a}/invoices/${r.id}`); const w = window.open('', '_blank'); if (w) { w.document.write(`<h1>${full.invoiceNumber}</h1><p>${full.customerEmail || ''}</p><p>${money(full.totalAmount, full.currency)}</p><pre>${JSON.stringify(full.lines || [], null, 2)}</pre>`); w.print(); } } catch (e) { setError(String(messageOf(e))); } }}>View</Button> }]}/>
    <Dialog open={open} onClose={() => setOpen(false)} fullWidth maxWidth="sm"><DialogTitle>{editingInvoiceId ? 'Edit draft invoice' : 'Create invoice draft'}</DialogTitle><DialogContent><Grid container spacing={2} sx={{ pt: 1 }}>{[['userId','Customer user ID'],['customerEmail','Customer email'],['orderId','Related order ID'],['description','Line description'],['hsnCode','HSN/SAC code'],['quantity','Quantity'],['unitPrice','Unit price'],['taxRate','Tax rate (0–1)'],['dueDate','Due date'],['notes','Notes']].map(([key,label]) => <Grid item xs={12} sm={key==='description'||key==='customerEmail'||key==='notes'?12:6} key={key}><TextField fullWidth label={label} error={key==='hsnCode'&&Boolean(hsnIssue)} helperText={key==='hsnCode'?hsnIssue||'Needed for the GST return HSN summary':undefined} type={key==='dueDate'?'date':'text'} multiline={key==='notes'} InputLabelProps={key==='dueDate'?{shrink:true}:undefined} disabled={Boolean(editingInvoiceId && editingLineCount > 1 && ['description','hsnCode','quantity','unitPrice','taxRate'].includes(key))} value={(form as any)[key]} onChange={e => setForm({ ...form, [key]: e.target.value })} /></Grid>)}<Grid item xs={12}><TextField select fullWidth label="Document type" value={form.type} onChange={e => setForm({ ...form, type: e.target.value })}><MenuItem value="INVOICE">Invoice</MenuItem><MenuItem value="CREDIT_NOTE">Credit note</MenuItem></TextField></Grid>
      {form.type === 'CREDIT_NOTE' && <Grid item xs={12}><TextField fullWidth label="Original invoice number" value={form.originalInvoiceNumber} onChange={e => setForm({ ...form, originalInvoiceNumber: e.target.value })} helperText="The invoice this credit note reduces" /></Grid>}
      <Grid item xs={12}><Divider><Typography variant="caption" color="text.secondary">GST details</Typography></Divider></Grid>
      <Grid item xs={12} sm={6}><TextField fullWidth label="Customer name" value={form.customerName} onChange={e => setForm({ ...form, customerName: e.target.value })} /></Grid>
      <Grid item xs={12} sm={6}><TextField fullWidth label="Customer GSTIN" value={form.customerGstin} error={Boolean(gstinIssue)} helperText={gstinIssue || 'Leave empty for an unregistered buyer'} onChange={e => setForm({ ...form, customerGstin: e.target.value.toUpperCase() })} /></Grid>
      <Grid item xs={12}><TextField select fullWidth label="Place of supply" value={form.customerGstin.trim() && !gstinIssue ? form.customerGstin.trim().slice(0, 2) : form.placeOfSupply} disabled={Boolean(form.customerGstin.trim()) && !gstinIssue} helperText={form.customerGstin.trim() ? 'Taken from the customer GSTIN' : 'Where the goods or services are delivered. Empty means your own state.'} onChange={e => setForm({ ...form, placeOfSupply: e.target.value })}><MenuItem value="">Your own state</MenuItem>{PLACES_OF_SUPPLY.map(p => <MenuItem key={p.code} value={p.code}>{p.code} · {p.name}</MenuItem>)}</TextField></Grid>
      <Grid item xs={12}><CurrencyRateFields base={base} currency={formCurrency} rate={form.exchangeRate} onCurrency={v => setForm(f => ({ ...f, currency: v }))} onRate={v => setForm(f => ({ ...f, exchangeRate: v }))} amount={Number(form.quantity || 0) * Number(form.unitPrice || 0) * (1 + Number(form.taxRate || 0))} /></Grid></Grid>{editingInvoiceId && editingLineCount > 1 && <Alert severity="info" sx={{ mt: 2 }}>This draft has multiple lines; its existing lines and totals are preserved while you edit the document details.</Alert>}{error && <Alert severity="error" sx={{ mt: 2 }}>{error}</Alert>}</DialogContent><DialogActions><Button onClick={() => setOpen(false)}>Cancel</Button><Button variant="contained" disabled={saving || Boolean(gstinIssue) || Boolean(hsnIssue) || Boolean(invoiceRateIssue)} onClick={save}>{saving?'Saving…':editingInvoiceId?'Save changes':'Save draft'}</Button></DialogActions></Dialog>
  </Box>;
}

export function JournalPage() {
  const [open,setOpen]=useState(false);const [error,setError]=useState('');const [notice,setNotice]=useState('');const [saving,setSaving]=useState(false);
  const { data: accountData }=useLoad<Row[]>(`${a}/accounts`);const accounts=Array.isArray(accountData)?accountData:[];
  const { data,busy,error:loadError,reload }=useLoad<Row>(`${a}/journals`);const rows:Row[]=data?.items||[];
  const [description,setDescription]=useState('');const [periodDate,setPeriodDate]=useState(new Date().toISOString().slice(0,10));const [key,setKey]=useState('');const [lines,setLines]=useState([{accountCode:'',debitAmount:'',creditAmount:'',description:''},{accountCode:'',debitAmount:'',creditAmount:'',description:''}]);
  const base=useBaseCurrency();const [entryCurrency,setEntryCurrency]=useState('');const [rate,setRate]=useState('1');const cur=entryCurrency||base;const rateIssue=rateProblem(cur,base,rate);
  const debit=lines.reduce((n,l)=>n+Number(l.debitAmount||0),0);const credit=lines.reduce((n,l)=>n+Number(l.creditAmount||0),0);const balanced=lines.length>=2&&debit>0&&Math.abs(debit-credit)<0.00005&&lines.every(l=>Boolean(l.accountCode)&&((Number(l.debitAmount||0)>0)!==(Number(l.creditAmount||0)>0)));
  const create=async(submit:boolean)=>{setSaving(true);setError('');try{const draft=(await api.post(`${a}/journals/drafts`,{description,periodDate,idempotencyKey:key||crypto.randomUUID(),currency:cur,exchangeRate:cur===base?undefined:Number(rate),lines:lines.map(l=>({...l,debitAmount:Number(l.debitAmount||0),creditAmount:Number(l.creditAmount||0)}))})).data;if(submit){await api.post(`${a}/journals/drafts/${draft.id}/submit`);setNotice('Journal submitted for approval. It will post to the ledger after another authorized user approves it.');}else setNotice(`Journal draft #${draft.id} saved. Submit it from Journal approvals when it is ready for review.`);setOpen(false);reload();}catch(e){setError(`${String(messageOf(e))} If the draft was saved, you can submit it from Journal approvals.`);reload();}finally{setSaving(false);}};
  const reverse=async(row:Row)=>{const reason=window.prompt(`Reason for reversing ${row.entryNumber}?`);if(reason===null)return;try{await api.post(`${a}/journals/${row.id}/reverse`,{reason});setNotice(`Reversal created for ${row.entryNumber}.`);reload();}catch(e){setError(String(messageOf(e)));}};
  return <Box><PageHeading title="Journal entries" detail="Review posted ledger entries. New manual journals require a second person’s approval." action={hasAccountingPermission("accounting:write") ? <Button variant="contained" onClick={()=>{setKey(crypto.randomUUID());setEntryCurrency('');setRate('1');setOpen(true);}}>New journal draft</Button> : undefined} />
    <Feedback busy={busy} error={loadError||error}/>{notice&&<Alert severity="success" onClose={()=>setNotice('')} sx={{mb:2}}>{notice}</Alert>}
    <DataTable rows={rows} columns={[{key:'entryNumber',label:'Entry'},{key:'periodDate',label:'Period',render:r=>dateValue(r.periodDate)},{key:'description',label:'Description'},{key:'referenceType',label:'Reference',render:r=>`${r.referenceType||''} ${r.referenceId||''}`},{key:'postedBy',label:'Posted by'},{key:'total',label:'Debits / credits',render:r=>{const d=(r.lines||[]).reduce((n: number,l:Row)=>n+Number(l.debitAmount||0),0);const c=(r.lines||[]).reduce((n: number,l:Row)=>n+Number(l.creditAmount||0),0);return `${money(d,r.currency)} / ${money(c,r.currency)}`;}},{key:'base',label:'In book currency',render:r=>{const lines=r.lines||[];if(!lines.length||!lines[0].baseCurrency||lines[0].baseCurrency===r.currency)return '—';return money(lines.reduce((n:number,l:Row)=>n+Number(l.baseDebit||0),0),lines[0].baseCurrency)+` @ ${Number(lines[0].exchangeRate)}`;}},{key:'actions',label:'Action',render:r=>r.reversal?<Chip size="small" label="Reversal" color="warning"/>:hasAccountingPermission("accounting:approve")?<Button size="small" color="warning" onClick={()=>reverse(r)}>Reverse</Button>:"—"}]}/>
    <Dialog open={open} onClose={()=>setOpen(false)} fullWidth maxWidth="md"><DialogTitle>Create journal draft</DialogTitle><DialogContent><Stack spacing={2} sx={{pt:1}}><Alert severity="info">Save the balanced entry as a draft, or submit it for review. A different authorized user must approve it before it is posted to the ledger.</Alert><TextField label="Description" value={description} onChange={e=>setDescription(e.target.value)} fullWidth/><TextField label="Period date" type="date" InputLabelProps={{shrink:true}} value={periodDate} onChange={e=>setPeriodDate(e.target.value)}/><CurrencyRateFields base={base} currency={cur} rate={rate} onCurrency={setEntryCurrency} onRate={setRate} amount={debit}/><Divider/><Typography fontWeight={700}>Journal lines · debits {money(debit,cur)} · credits {money(credit,cur)}</Typography>{lines.map((line,i)=><Grid container spacing={1} key={i} alignItems="center"><Grid item xs={12} sm={4}><TextField select fullWidth size="small" label="Account" value={line.accountCode} onChange={e=>setLines(lines.map((x,j)=>j===i?{...x,accountCode:e.target.value}:x))}>{accounts.filter(x=>x.active).map(x=><MenuItem key={x.code} value={x.code}>{x.code} · {x.name}</MenuItem>)}</TextField></Grid><Grid item xs={6} sm={2}><TextField fullWidth size="small" label="Debit" type="number" value={line.debitAmount} onChange={e=>setLines(lines.map((x,j)=>j===i?{...x,debitAmount:e.target.value,creditAmount:e.target.value?'':'0'}:x))}/></Grid><Grid item xs={6} sm={2}><TextField fullWidth size="small" label="Credit" type="number" value={line.creditAmount} onChange={e=>setLines(lines.map((x,j)=>j===i?{...x,creditAmount:e.target.value,debitAmount:e.target.value?'':'0'}:x))}/></Grid><Grid item xs={10} sm={3}><TextField fullWidth size="small" label="Line note" value={line.description} onChange={e=>setLines(lines.map((x,j)=>j===i?{...x,description:e.target.value}:x))}/></Grid><Grid item xs={2} sm={1}><Button onClick={()=>setLines(lines.filter((_,j)=>j!==i))}>×</Button></Grid></Grid>)}<Button onClick={()=>setLines([...lines,{accountCode:'',debitAmount:'',creditAmount:'',description:''}])}>Add line</Button>{!balanced&&<Alert severity="warning">The entry can be saved or submitted only when every line has one positive side and total debits equal credits.</Alert>}{error&&<Alert severity="error">{error}</Alert>}</Stack></DialogContent><DialogActions><Button onClick={()=>setOpen(false)}>Cancel</Button><Button disabled={!balanced||saving||!description||Boolean(rateIssue)} onClick={()=>void create(false)}>{saving?'Saving…':'Save draft'}</Button><Button variant="contained" disabled={!balanced||saving||!description||Boolean(rateIssue)} onClick={()=>void create(true)}>{saving?'Submitting…':'Submit for approval'}</Button></DialogActions></Dialog>
  </Box>;
}

export function JournalApprovalsPage() {
  const [status,setStatus]=useState('');const [notice,setNotice]=useState('');const [failure,setFailure]=useState('');const [actionId,setActionId]=useState<number|null>(null);const [editing,setEditing]=useState<Row|null>(null);const [savingEdit,setSavingEdit]=useState(false);
  const {data,busy,error,reload}=useLoad<Row>(`${a}/journals/drafts`,{status:status||undefined});const rows:Row[]=data?.items||[];const userId=currentAccountingUserId();const {data:accountData}=useLoad<Row[]>(`${a}/accounts`);const accounts=Array.isArray(accountData)?accountData.filter(account=>account.active):[];
  const decide=async(row:Row,decision:'approve'|'reject')=>{let reason='';if(decision==='reject'){const answer=window.prompt('Provide a rejection reason (at least 10 characters):');if(answer===null)return;reason=answer.trim();if(reason.length<10){setFailure('A rejection reason of at least 10 characters is required.');return;}}setFailure('');setActionId(Number(row.id));try{await api.post(`${a}/journals/drafts/${row.id}/${decision}`,decision==='reject'?{reason}:{});setNotice(decision==='approve'?`Journal draft #${row.id} approved and posted to the ledger.`:`Journal draft #${row.id} rejected. The creator can revise it before resubmission.`);reload();}catch(e){setFailure(String(messageOf(e)));}finally{setActionId(null);}};
  const submit=async(row:Row)=>{setFailure('');setActionId(Number(row.id));try{await api.post(`${a}/journals/drafts/${row.id}/submit`);setNotice(`Journal draft #${row.id} submitted for approval.`);reload();}catch(e){setFailure(String(messageOf(e)));}finally{setActionId(null);}};
  const openEdit=(row:Row)=>{setFailure('');setEditing({...row,lines:(row.lines||[]).map((line:Row)=>({...line,debitAmount:String(line.debitAmount??''),creditAmount:String(line.creditAmount??'')}))});};
  const editLines:Row[]=editing?.lines||[];const editDebits=editLines.reduce((sum:number,line:Row)=>sum+Number(line.debitAmount||0),0);const editCredits=editLines.reduce((sum:number,line:Row)=>sum+Number(line.creditAmount||0),0);const editBalanced=!!editing&&editLines.length>=2&&editDebits>0&&Math.abs(editDebits-editCredits)<0.00005&&editLines.every((line:Row)=>Boolean(line.accountCode)&&((Number(line.debitAmount||0)>0)!==(Number(line.creditAmount||0)>0)));
  const saveEdit=async()=>{if(!editing)return;setSavingEdit(true);setFailure('');try{await api.put(`${a}/journals/drafts/${editing.id}`,{description:editing.description,referenceType:editing.referenceType,referenceId:editing.referenceId,periodDate:dateValue(editing.periodDate),currency:editing.currency,exchangeRate:(editing.currency||base)===base?undefined:Number(editing.exchangeRate),lines:editLines.map((line:Row)=>({...line,debitAmount:Number(line.debitAmount||0),creditAmount:Number(line.creditAmount||0)}))});setNotice(`Journal draft #${editing.id} updated. Submit it when it is ready for review.`);setEditing(null);reload();}catch(e){setFailure(String(messageOf(e)));}finally{setSavingEdit(false);}};
  const canApprove=hasAccountingPermission('accounting:approve');const canWrite=hasAccountingPermission('accounting:write');const base=useBaseCurrency();const editCurrency=String(editing?.currency||base);const editRate=String(editing?.exchangeRate??'1');const editRateIssue=rateProblem(editCurrency,base,editRate);
  return <Box><PageHeading title="Journal approvals" detail="Separate preparation from approval. Approved journals are posted to the ledger with an audit trail." />
    <Stack direction={{xs:'column',sm:'row'}} spacing={1.5} sx={{mb:2}}><TextField select size="small" label="Workflow status" value={status} onChange={e=>setStatus(e.target.value)} sx={{minWidth:220}}><MenuItem value="">All statuses</MenuItem>{['DRAFT','PENDING_APPROVAL','REJECTED','POSTED'].map(value=><MenuItem key={value} value={value}>{value.replace('_',' ')}</MenuItem>)}</TextField><Button variant="outlined" onClick={reload}>Refresh</Button></Stack>
    <Feedback busy={busy} error={error||failure}/>{notice&&<Alert severity="success" onClose={()=>setNotice('')} sx={{mb:2}}>{notice}</Alert>}
    <DataTable rows={rows} empty="No journal drafts in this workflow state." columns={[{key:'id',label:'Draft'},{key:'periodDate',label:'Period',render:r=>dateValue(r.periodDate)},{key:'description',label:'Description'},{key:'createdByEmail',label:'Prepared by'},{key:'total',label:'Debits / credits',render:r=>{const d=(r.lines||[]).reduce((n:number,l:Row)=>n+Number(l.debitAmount||0),0);const c=(r.lines||[]).reduce((n:number,l:Row)=>n+Number(l.creditAmount||0),0);return `${money(d,r.currency)} / ${money(c,r.currency)}`;}},{key:'status',label:'Status',render:r=><Chip size="small" label={String(r.status).replace('_',' ')} color={r.status==='POSTED'?'success':r.status==='REJECTED'?'error':r.status==='PENDING_APPROVAL'?'warning':'default'}/>},{key:'decisionNote',label:'Decision note',render:r=>r.decisionNote||'—'},{key:'actions',label:'Actions',render:r=>{const owner=userId!==null&&Number(r.createdByUserId)===userId;const pending=r.status==='PENDING_APPROVAL';if(pending&&canApprove&&!owner)return <Stack direction="row" spacing={.5}><Button size="small" variant="contained" disabled={actionId===Number(r.id)} onClick={()=>void decide(r,'approve')}>Approve</Button><Button size="small" color="error" disabled={actionId===Number(r.id)} onClick={()=>void decide(r,'reject')}>Reject</Button></Stack>;if((r.status==='DRAFT'||r.status==='REJECTED')&&canWrite&&owner)return <Stack direction="row" spacing={.5}><Button size="small" disabled={actionId===Number(r.id)} onClick={()=>openEdit(r)}>Edit</Button><Button size="small" disabled={actionId===Number(r.id)} onClick={()=>void submit(r)}>Submit</Button></Stack>;return pending&&owner?'Awaiting another approver':'—';}}]}/>
    <Dialog open={Boolean(editing)} onClose={()=>setEditing(null)} fullWidth maxWidth="md"><DialogTitle>{editing?.status==='REJECTED'?'Revise rejected journal':'Edit journal draft'}</DialogTitle><DialogContent><Stack spacing={2} sx={{pt:1}}>{editing?.decisionNote&&<Alert severity="warning">Reviewer feedback: {editing.decisionNote}</Alert>}<TextField label="Description" value={editing?.description||''} onChange={e=>setEditing((current:Row|null)=>current?{...current,description:e.target.value}:current)} fullWidth/><Grid container spacing={2}><Grid item xs={12} sm={6}><TextField fullWidth label="Period date" type="date" InputLabelProps={{shrink:true}} value={dateValue(editing?.periodDate)} onChange={e=>setEditing((current:Row|null)=>current?{...current,periodDate:e.target.value}:current)}/></Grid></Grid><CurrencyRateFields base={base} currency={editCurrency} rate={editRate} onCurrency={v=>setEditing((current:Row|null)=>current?{...current,currency:v}:current)} onRate={v=>setEditing((current:Row|null)=>current?{...current,exchangeRate:v}:current)} amount={editDebits}/><Divider/><Typography fontWeight={700}>Journal lines · debits {money(editDebits,editing?.currency|| businessCurrency())} · credits {money(editCredits,editing?.currency|| businessCurrency())}</Typography>{editLines.map((line:Row,index:number)=><Grid container spacing={1} key={line.id||index} alignItems="center"><Grid item xs={12} sm={4}><TextField select fullWidth size="small" label="Account" value={line.accountCode||''} onChange={e=>setEditing((current:Row|null)=>current?{...current,lines:current.lines.map((item:Row,i:number)=>i===index?{...item,accountCode:e.target.value}:item)}:current)}>{accounts.map(account=><MenuItem key={account.code} value={account.code}>{account.code} · {account.name}</MenuItem>)}</TextField></Grid><Grid item xs={6} sm={2}><TextField fullWidth size="small" label="Debit" type="number" value={line.debitAmount} onChange={e=>setEditing((current:Row|null)=>current?{...current,lines:current.lines.map((item:Row,i:number)=>i===index?{...item,debitAmount:e.target.value,creditAmount:e.target.value?'':'0'}:item)}:current)}/></Grid><Grid item xs={6} sm={2}><TextField fullWidth size="small" label="Credit" type="number" value={line.creditAmount} onChange={e=>setEditing((current:Row|null)=>current?{...current,lines:current.lines.map((item:Row,i:number)=>i===index?{...item,creditAmount:e.target.value,debitAmount:e.target.value?'':'0'}:item)}:current)}/></Grid><Grid item xs={10} sm={3}><TextField fullWidth size="small" label="Line note" value={line.description||''} onChange={e=>setEditing((current:Row|null)=>current?{...current,lines:current.lines.map((item:Row,i:number)=>i===index?{...item,description:e.target.value}:item)}:current)}/></Grid><Grid item xs={2} sm={1}><Button onClick={()=>setEditing((current:Row|null)=>current?{...current,lines:current.lines.filter((_:Row,i:number)=>i!==index)}:current)}>×</Button></Grid></Grid>)}<Button onClick={()=>setEditing((current:Row|null)=>current?{...current,lines:[...current.lines,{accountCode:'',debitAmount:'',creditAmount:'',description:''}]}:current)}>Add line</Button>{!editBalanced&&<Alert severity="warning">Each line needs one positive debit or credit, and total debits must equal total credits.</Alert>}{failure&&<Alert severity="error">{failure}</Alert>}</Stack></DialogContent><DialogActions><Button onClick={()=>setEditing(null)}>Cancel</Button><Button variant="contained" disabled={!editBalanced||savingEdit||!editing?.description||Boolean(editRateIssue)} onClick={()=>void saveEdit()}>{savingEdit?'Saving…':'Save changes'}</Button></DialogActions></Dialog>
  </Box>;
}

export function ChartOfAccountsPage() {
  const {data,busy,error,reload}=useLoad<Row[]>(`${a}/accounts`);const rows=Array.isArray(data)?data:[];
  const [open,setOpen]=useState(false);const [editingId,setEditingId]=useState<number|null>(null);const [failure,setFailure]=useState('');
  const empty={code:'',name:'',accountType:'ASSET',normalBalance:'DEBIT',parentCode:'',description:'',cashAccount:false,active:true};const [form,setForm]=useState({...empty});
  const treeRows:Row[]=[];const visited=new Set<number>();const appendChildren=(parent:string,depth:number)=>rows.filter(row=>(row.parentCode||'')===parent&&!visited.has(Number(row.id))).sort((x,y)=>String(x.code).localeCompare(String(y.code))).forEach(row=>{visited.add(Number(row.id));treeRows.push({...row,treeDepth:depth});appendChildren(String(row.code),depth+1);});appendChildren('',0);rows.filter(row=>!visited.has(Number(row.id))).forEach(row=>treeRows.push({...row,treeDepth:0}));
  const add=()=>{setFailure('');setEditingId(null);setForm({...empty});setOpen(true);};
  const edit=(row:Row)=>{setFailure('');setEditingId(row.id);setForm({code:row.code,name:row.name,accountType:row.accountType,normalBalance:row.normalBalance,parentCode:row.parentCode||'',description:row.description||'',cashAccount:Boolean(row.cashAccount),active:Boolean(row.active)});setOpen(true);};
  const submit=async()=>{setFailure('');try{if(editingId)await api.put(`${a}/accounts/${editingId}`,form);else await api.post(`${a}/accounts`,{code:form.code,name:form.name,accountType:form.accountType,normalBalance:form.normalBalance,parentCode:form.parentCode,description:form.description,cashAccount:form.cashAccount});setOpen(false);reload();}catch(e){setFailure(String(messageOf(e)));}};
  return <Box><PageHeading title="Chart of accounts" detail="Organize account codes into a hierarchy and maintain reporting attributes." action={hasAccountingPermission("accounting:write") ? <Button variant="contained" onClick={add}>Add account</Button> : undefined}/><Feedback busy={busy} error={error}/><DataTable rows={treeRows} columns={[{key:'code',label:'Code'},{key:'name',label:'Account',render:r=><Typography sx={{pl:Math.min(r.treeDepth,6)*2,fontWeight:r.treeDepth===0?800:500}}>{r.treeDepth>0?'↳ ':''}{r.name}</Typography>},{key:'accountType',label:'Type'},{key:'normalBalance',label:'Normal balance'},{key:'parentCode',label:'Parent',render:r=>r.parentCode||'Top level'},{key:'cashAccount',label:'Cash account',render:r=><Chip size="small" label={r.cashAccount?'Yes':'No'} color={r.cashAccount?'success':'default'}/>},{key:'active',label:'Status',render:r=><Chip size="small" label={r.active?'Active':'Inactive'} color={r.active?'success':'default'}/>},{key:'actions',label:'Actions',render:r=>hasAccountingPermission("accounting:write")?<Button size="small" onClick={()=>edit(r)}>Edit</Button>:"—"} ]}/>
    <Dialog open={open} onClose={()=>setOpen(false)} fullWidth maxWidth="sm"><DialogTitle>{editingId?'Edit account':'Add account'}</DialogTitle><DialogContent><Stack spacing={2} sx={{pt:1}}><TextField label="Code" value={form.code} disabled={Boolean(editingId)} onChange={e=>setForm({...form,code:e.target.value.toUpperCase()})}/><TextField label="Name" value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/><TextField select label="Parent account" value={form.parentCode} onChange={e=>setForm({...form,parentCode:e.target.value})}><MenuItem value="">Top level</MenuItem>{rows.filter(r=>r.active&&r.id!==editingId).map(r=><MenuItem key={r.id} value={r.code}>{r.code} · {r.name}</MenuItem>)}</TextField><TextField label="Description" multiline minRows={2} value={form.description} onChange={e=>setForm({...form,description:e.target.value})}/><TextField select label="Account type" value={form.accountType} onChange={e=>setForm({...form,accountType:e.target.value})}>{['ASSET','LIABILITY','EQUITY','REVENUE','EXPENSE'].map(v=><MenuItem key={v} value={v}>{v}</MenuItem>)}</TextField><TextField select label="Normal balance" value={form.normalBalance} onChange={e=>setForm({...form,normalBalance:e.target.value})}><MenuItem value="DEBIT">Debit</MenuItem><MenuItem value="CREDIT">Credit</MenuItem></TextField><TextField select label="Cash account" value={String(form.cashAccount)} onChange={e=>setForm({...form,cashAccount:e.target.value==='true'})}><MenuItem value="false">No</MenuItem><MenuItem value="true">Yes</MenuItem></TextField>{editingId&&<TextField select label="Status" value={String(form.active)} onChange={e=>setForm({...form,active:e.target.value==='true'})}><MenuItem value="true">Active</MenuItem><MenuItem value="false">Inactive</MenuItem></TextField>}{failure&&<Alert severity="error">{failure}</Alert>}</Stack></DialogContent><DialogActions><Button onClick={()=>setOpen(false)}>Cancel</Button><Button variant="contained" onClick={submit}>{editingId?'Save changes':'Create account'}</Button></DialogActions></Dialog>
  </Box>;
}

export function ReportsPage() {
  const [type,setType]=useState('profit-loss');const [start,setStart]=useState(new Date(new Date().getFullYear(),new Date().getMonth(),1).toISOString().slice(0,10));const [end,setEnd]=useState(new Date().toISOString().slice(0,10));const [report,setReport]=useState<Row|null>(null);const [busy,setBusy]=useState(false);const [error,setError]=useState('');
  const run=async()=>{setBusy(true);setError('');try{const params=type==='balance-sheet'?{asOfDate:end,currency: businessCurrency()}:{startDate:start,endDate:end,currency: businessCurrency()};const r=await api.get(`${a}/reports/${type}`,{params});setReport(r.data);}catch(e){setError(String(messageOf(e)));}finally{setBusy(false);}};
  return <Box><PageHeading title="Financial reports" detail="Review recorded journal and invoice activity for a selected period." action={<Button variant="contained" onClick={run}>Generate report</Button>}/><Grid container spacing={1.5} sx={{mb:2}}><Grid item xs={12} sm={4}><TextField select fullWidth label="Report" value={type} onChange={e=>setType(e.target.value)}>{[['profit-loss','Profit & loss'],['balance-sheet','Balance sheet'],['tax-summary','Tax summary'],['cash-flow','Cash flow']].map(([v,l])=><MenuItem value={v} key={v}>{l}</MenuItem>)}</TextField></Grid><Grid item xs={6} sm={4}><TextField fullWidth type="date" label={type==='balance-sheet'?'As of':'From'} InputLabelProps={{shrink:true}} value={type==='balance-sheet'?end:start} onChange={e=>type==='balance-sheet'?setEnd(e.target.value):setStart(e.target.value)}/></Grid>{type!=='balance-sheet'&&<Grid item xs={6} sm={4}><TextField fullWidth type="date" label="To" InputLabelProps={{shrink:true}} value={end} onChange={e=>setEnd(e.target.value)}/></Grid>}</Grid><Feedback busy={busy} error={error}/>{report&&<Paper variant="outlined" sx={{p:2.5}}><Stack direction="row" justifyContent="space-between" sx={{mb:2}}><Box><Typography variant="h6" fontWeight={800}>{String(report.reportType).replace('_',' ')}</Typography><Typography color="text.secondary">{dateValue(report.periodStart)} – {dateValue(report.periodEnd)} · {report.currency}</Typography></Box><Button startIcon={<DownloadRounded/>} onClick={()=>{const blob=new Blob([JSON.stringify(report,null,2)],{type:'application/json'});const u=URL.createObjectURL(blob);const a=document.createElement('a');a.href=u;a.download=`${type}-${end}.json`;a.click();URL.revokeObjectURL(u);}}>Download</Button></Stack><Grid container spacing={2}>{Object.entries(report).filter(([,v])=>typeof v==='number').map(([k,v])=><Grid item xs={12} sm={4} key={k}><Card variant="outlined"><CardContent><Typography color="text.secondary">{k}</Typography><Typography variant="h5" fontWeight={800}>{money(v as number)}</Typography></CardContent></Card></Grid>)}</Grid><Divider sx={{my:2}}/><Typography variant="body2" color="text.secondary">{report.disclaimer}</Typography><Box component="pre" sx={{overflow:'auto',maxHeight:420,p:2,bgcolor:'#F8FAFC',borderRadius:2,fontSize:12}}>{JSON.stringify(report,null,2)}</Box></Paper>}</Box>;
}
export function ReconciliationPage() {
  const [status,setStatus]=useState('PENDING_REVIEW');const {data,busy,error,reload}=useLoad<Row>('/api/accounting/admin/ledger',{reconciliationStatus:status,page:0,size:25});const rows:Row[]=data?.content||[];const [failure,setFailure]=useState('');
  const update=async(row:Row,next:string)=>{try{await api.put(`/api/accounting/admin/reconciliation/${row.id}`,{status:next,notes:'Updated from accounting reconciliation workspace.'});reload();}catch(e){setFailure(String(messageOf(e)));}};
  return <Box><PageHeading title="Reconciliation" detail="Compare internal ledger entries with provider references and flag discrepancies."/><TextField select size="small" label="Reconciliation status" value={status} onChange={e=>setStatus(e.target.value)} sx={{mb:2,minWidth:200}}>{['PENDING_REVIEW','RECONCILED','FLAGGED_DISCREPANCY'].map(s=><MenuItem value={s} key={s}>{s}</MenuItem>)}</TextField><Feedback busy={busy} error={error||failure}/><DataTable rows={rows} columns={[{key:'id',label:'Transaction'},{key:'referenceId',label:'Internal reference'},{key:'paymentProvider',label:'Provider'},{key:'providerReference',label:'Provider reference'},{key:'type',label:'Type'},{key:'amount',label:'Amount',render:r=>money(r.amount,r.currency|| businessCurrency())},{key:'status',label:'Payment status'},{key:'reconciliationStatus',label:'Review'},{key:'reconciliationNotes',label:'Notes',render:r=>r.reconciliationNotes||'—'},{key:'actions',label:'Update',render:r=><Stack direction="row" spacing={1}><Button disabled={!hasAccountingPermission("accounting:reconcile")} size="small" onClick={()=>update(r,'RECONCILED')}>Match</Button><Button size="small" color="warning" onClick={()=>update(r,'FLAGGED_DISCREPANCY')}>Flag</Button></Stack>}]}/></Box>;
}

export function AccountingPeriodsPage() {
  const { data, busy, error, reload } = useLoad<Row[]>(`${a}/periods`);
  const rows = Array.isArray(data) ? data : [];
  const [open, setOpen] = useState(false);
  const [failure, setFailure] = useState('');
  const [notice, setNotice] = useState('');
  const [saving, setSaving] = useState(false);
  const [form, setForm] = useState({ periodName: '', startDate: '', endDate: '' });

  const save = async () => {
    setSaving(true); setFailure('');
    try {
      await api.post(`${a}/periods`, form);
      setOpen(false); setNotice('Accounting period created.'); reload();
    } catch (e) { setFailure(String(messageOf(e))); }
    finally { setSaving(false); }
  };
  const transition = async (row: Row, action: 'close' | 'reopen') => {
    const reason = window.prompt(action === 'close'
      ? `Close ${row.periodName}. Add a close note:`
      : `Reopen ${row.periodName}. Explain why:`);
    if (reason === null) return;
    try {
      await api.post(`${a}/periods/${row.id}/${action}`, { reason });
      setNotice(`${row.periodName} ${action === 'close' ? 'closed' : 'reopened'}.`); reload();
    } catch (e) { setFailure(String(messageOf(e))); }
  };

  return <Box>
    <PageHeading title="Accounting periods" detail="Create fiscal periods, close reviewed periods, and keep closed dates out of new journal postings."
      action={hasAccountingPermission('accounting:write') ? <Button variant="contained" onClick={() => { setFailure(''); setOpen(true); }}>New period</Button> : undefined} />
    <Alert severity="info" sx={{ mb: 2 }}>Closing is auditable and blocks future journal entries and reversals dated inside the period. Reopening requires an explanation.</Alert>
    <Feedback busy={busy} error={error || failure} />
    {notice && <Alert severity="success" onClose={() => setNotice('')} sx={{ mb: 2 }}>{notice}</Alert>}
    <DataTable rows={rows} columns={[
      { key: 'periodName', label: 'Period' }, { key: 'startDate', label: 'From', render: r => dateValue(r.startDate) },
      { key: 'endDate', label: 'Through', render: r => dateValue(r.endDate) },
      { key: 'status', label: 'Status', render: r => <Chip size="small" label={r.status} color={r.status === 'CLOSED' ? 'default' : 'success'} /> },
      { key: 'closedBy', label: 'Closed by', render: r => r.closedBy || '—' },
      { key: 'closedAt', label: 'Closed at', render: r => r.closedAt ? new Date(r.closedAt).toLocaleString() : '—' },
      { key: 'closeReason', label: 'Close note', render: r => r.closeReason || '—' },
      { key: 'actions', label: 'Actions', render: r => !hasAccountingPermission('accounting:approve') ? '—' : r.status === 'CLOSED'
        ? <Button size="small" color="warning" onClick={() => transition(r, 'reopen')}>Reopen</Button>
        : <Button size="small" color="primary" onClick={() => transition(r, 'close')}>Close period</Button> },
    ]} />
    <Dialog open={open} onClose={() => setOpen(false)} fullWidth maxWidth="sm">
      <DialogTitle>Create accounting period</DialogTitle>
      <DialogContent><Stack spacing={2} sx={{ pt: 1 }}>
        <TextField autoFocus label="Period name" placeholder="FY 2026 Q4" value={form.periodName} onChange={e => setForm({ ...form, periodName: e.target.value })} />
        <TextField type="date" label="Start date" InputLabelProps={{ shrink: true }} value={form.startDate} onChange={e => setForm({ ...form, startDate: e.target.value })} />
        <TextField type="date" label="End date" InputLabelProps={{ shrink: true }} value={form.endDate} onChange={e => setForm({ ...form, endDate: e.target.value })} />
        {failure && <Alert severity="error">{failure}</Alert>}
      </Stack></DialogContent>
      <DialogActions><Button onClick={() => setOpen(false)}>Cancel</Button>
        <Button variant="contained" disabled={saving || !form.periodName || !form.startDate || !form.endDate} onClick={save}>{saving ? 'Saving…' : 'Create period'}</Button>
      </DialogActions>
    </Dialog>
  </Box>;
}


// One row per invoice or note in a GSTR-1 section: B2B and CDNR are grouped by buyer GSTIN, B2CL by place of supply, exports by type.
function gstDocuments(groups: Row[] | undefined, key: 'inv' | 'nt'): Row[] {
  const out: Row[] = [];
  for (const group of groups || []) for (const doc of group[key] || []) {
    const items: Row[] = (doc.itms || []).map((i: Row) => i.itm_det || i);
    const sum = (k: string) => items.reduce((n, i) => n + Number(i[k] || 0), 0);
    out.push({ ...doc, ctin: group.ctin, pos: doc.pos || group.pos, exp_typ: group.exp_typ, txval: sum('txval'), iamt: sum('iamt'), camt: sum('camt'), samt: sum('samt') });
  }
  return out;
}
const inr = (v: unknown) => money(v, 'INR');
const taxColumns = [{ key: 'txval', label: 'Taxable value', render: (r: Row) => inr(r.txval) }, { key: 'iamt', label: 'IGST', render: (r: Row) => inr(r.iamt) }, { key: 'camt', label: 'CGST', render: (r: Row) => inr(r.camt) }, { key: 'samt', label: 'SGST/UTGST', render: (r: Row) => inr(r.samt) }];
function GstSection({ title, hint, rows, columns }: { title: string; hint: string; rows: Row[]; columns: { key: string; label: string; render?: (row: Row) => React.ReactNode }[] }) {
  return <Box sx={{ mb: 3 }}><Typography variant="h6" fontWeight={800}>{title} <Chip size="small" label={rows.length} sx={{ ml: 1 }} /></Typography><Typography variant="body2" color="text.secondary" sx={{ mb: 1 }}>{hint}</Typography><DataTable rows={rows} columns={columns} empty="Nothing in this section for the month." /></Box>;
}

function GstSettingsCard({ onSaved }: { onSaved: () => void }) {
  const { data, busy, error, reload } = useLoad<Row>(`${a}/settings`); const canWrite = hasAccountingPermission('accounting:write');
  const [form, setForm] = useState<Row | null>(null); const [saving, setSaving] = useState(false); const [failure, setFailure] = useState(''); const [notice, setNotice] = useState('');
  useEffect(() => { if (data) setForm({ baseCurrency: data.baseCurrency || '', gstin: data.gstin || '', legalName: data.legalName || '' }); }, [data]);
  const gstinIssue = gstinProblem(String(form?.gstin || ''));
  const save = async () => { if (!form) return; setSaving(true); setFailure(''); try { await api.put(`${a}/settings`, { baseCurrency: String(form.baseCurrency).toUpperCase(), gstin: String(form.gstin).trim() || null, legalName: String(form.legalName).trim() || null }); setNotice('GST settings saved.'); reload(); onSaved(); } catch (e) { setFailure(String(messageOf(e))); } finally { setSaving(false); } };
  return <Paper variant="outlined" sx={{ p: 2.5, mb: 3 }}><Typography variant="h6" fontWeight={800}>Books and GST registration</Typography>
    <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>Reports are in the base currency. GST returns need INR books and your GSTIN; the state is taken from the GSTIN.</Typography>
    <Feedback busy={busy} error={error} />
    {form && <Grid container spacing={2}>
      <Grid item xs={12} sm={3}><TextField fullWidth size="small" label="Base currency" inputProps={{ maxLength: 3 }} disabled={!canWrite || Boolean(data?.baseCurrencyLocked)} helperText={data?.baseCurrencyLocked ? 'Fixed once journals are posted' : 'Set before posting journals'} value={form.baseCurrency} onChange={e => setForm({ ...form, baseCurrency: e.target.value.toUpperCase() })} /></Grid>
      <Grid item xs={12} sm={4}><TextField fullWidth size="small" label="Your GSTIN" disabled={!canWrite} error={Boolean(gstinIssue)} helperText={gstinIssue || (data?.stateCode ? `State: ${data.stateCode} · ${placeName(data.stateCode)}` : 'Leave empty if not registered')} value={form.gstin} onChange={e => setForm({ ...form, gstin: e.target.value.toUpperCase() })} /></Grid>
      <Grid item xs={12} sm={5}><TextField fullWidth size="small" label="Legal name (as registered)" disabled={!canWrite} value={form.legalName} onChange={e => setForm({ ...form, legalName: e.target.value })} /></Grid>
      {canWrite && <Grid item xs={12}><Button variant="contained" disabled={saving || Boolean(gstinIssue)} onClick={() => void save()}>{saving ? 'Saving…' : 'Save settings'}</Button></Grid>}
    </Grid>}
    {failure && <Alert severity="error" sx={{ mt: 2 }}>{failure}</Alert>}{notice && <Alert severity="success" sx={{ mt: 2 }} onClose={() => setNotice('')}>{notice}</Alert>}
  </Paper>;
}

export function GstReturnsPage() {
  const [month, setMonth] = useState(lastMonth()); const [version, setVersion] = useState(0); const [failure, setFailure] = useState('');
  const { data, busy, error, reload } = useLoad<Row>(`${a}/gst/returns`, { month, version });
  const g1: Row = data?.gstr1 || {}; const g3: Row = data?.gstr3b || {}; const canExport = hasAccountingPermission('accounting:export');
  const b2b = gstDocuments(g1.b2b, 'inv'); const b2cl = gstDocuments(g1.b2cl, 'inv'); const cdnr = gstDocuments(g1.cdnr, 'nt'); const exp = gstDocuments(g1.exp, 'inv');
  const docColumns = (party: boolean) => [{ key: 'inum', label: 'Number', render: (r: Row) => r.inum || r.nt_num }, { key: 'idt', label: 'Date', render: (r: Row) => r.idt || r.nt_dt }, ...(party ? [{ key: 'ctin', label: 'Buyer GSTIN' }] : []), { key: 'pos', label: 'Place of supply', render: (r: Row) => r.pos ? `${r.pos} · ${placeName(r.pos)}` : '—' }, { key: 'val', label: 'Document value', render: (r: Row) => inr(r.val) }, ...taxColumns];
  const sup: Row = g3.sup_details || {}; const row3b = (label: string, v: Row | undefined) => ({ label, txval: v?.txval, iamt: v?.iamt, camt: v?.camt, samt: v?.samt });
  const save = async (kind: 'json' | 'csv') => { setFailure(''); try { await download(`${a}/gst/gstr1.${kind}`, { month }, `GSTR1-${month}.${kind}`); } catch (e) { setFailure(String(messageOf(e))); } };
  const missingSetup = /GSTIN|INR/.test(error);
  return <Box><PageHeading title="GST returns" detail="GSTR-1 and GSTR-3B for a month, from issued invoices, credit notes and Point of Sale GST invoices."
    action={<Stack direction="row" spacing={1}><TextField size="small" type="month" label="Return period" InputLabelProps={{ shrink: true }} value={month} onChange={e => setMonth(e.target.value)} /><Button variant="outlined" startIcon={<DownloadRounded />} disabled={!canExport || !data} onClick={() => void save('json')}>GSTR-1 JSON</Button><Button variant="outlined" disabled={!canExport || !data} onClick={() => void save('csv')}>CSV</Button></Stack>} />
    <GstSettingsCard onSaved={() => setVersion(v => v + 1)} />
    {missingSetup ? <Alert severity="info" sx={{ mb: 2 }}>{error}</Alert> : <Feedback busy={busy} error={error} onRetry={reload} />}
    {failure && <Alert severity="error" sx={{ mb: 2 }}>{failure}</Alert>}
    {data && <>
      <Alert severity="info" sx={{ mb: 2 }}>{data.note} Sources: {data.sources?.invoices ?? 0} invoices and credit notes, {data.sources?.posInvoices ?? 0} POS GST invoices.</Alert>
      {(data.warnings || []).length > 0 && <Alert severity="warning" sx={{ mb: 2 }}><Typography fontWeight={700}>Check before filing</Typography>{(data.warnings as string[]).slice(0, 20).map(w => <div key={w}>{w}</div>)}{data.warnings.length > 20 && <div>…and {data.warnings.length - 20} more.</div>}</Alert>}
      <Typography variant="h5" fontWeight={800} sx={{ mb: 1 }}>GSTR-3B summary</Typography>
      <Box sx={{ mb: 3 }}><DataTable rows={[row3b('3.1(a) Outward taxable supplies', sup.osup_det), row3b('3.1(b) Zero-rated supplies (exports)', sup.osup_zero), row3b('3.1(c) Nil-rated and exempt', sup.osup_nil_exmp), row3b('Tax payable', g3.tax_payable)]} columns={[{ key: 'label', label: 'Table' }, ...taxColumns]} /></Box>
      <Typography variant="body2" color="text.secondary" sx={{ mb: 3 }}>{g3.itc_note} Inter-state supplies to unregistered buyers (3.2): {(g3.inter_sup?.unreg_details || []).map((r: Row) => `${r.pos} ${inr(r.txval)}`).join(', ') || 'none'}.</Typography>
      <Typography variant="h5" fontWeight={800} sx={{ mb: 1 }}>GSTR-1 · {g1.fp}</Typography>
      <GstSection title="B2B invoices (4A)" hint="Sales to GST-registered buyers." rows={b2b} columns={docColumns(true)} />
      <GstSection title="B2C large (5)" hint="Inter-state sales to unregistered buyers above ₹1,00,000 per invoice." rows={b2cl} columns={docColumns(false)} />
      <GstSection title="B2C small (7)" hint="Other sales to unregistered buyers, totalled by place of supply and rate, after credit notes." rows={g1.b2cs || []} columns={[{ key: 'sply_ty', label: 'Supply' }, { key: 'pos', label: 'Place of supply', render: r => `${r.pos} · ${placeName(r.pos)}` }, { key: 'rt', label: 'Rate %' }, ...taxColumns]} />
      <GstSection title="Credit notes to registered buyers (9B)" hint="Credit notes against B2B invoices." rows={cdnr} columns={[...docColumns(true), { key: 'orig_inum', label: 'Original invoice', render: r => r.orig_inum || '—' }]} />
      <GstSection title="Exports (6A)" hint="Supplies with place of supply 96 (outside India)." rows={exp} columns={[{ key: 'exp_typ', label: 'Type', render: r => r.exp_typ === 'WPAY' ? 'With IGST' : 'Under LUT (no tax)' }, ...docColumns(false).filter(c => c.key !== 'pos')]} />
      <GstSection title="HSN summary (12)" hint="Taxable value and tax by HSN/SAC code and rate." rows={[...(g1.hsn?.hsn_b2b || []).map((r: Row) => ({ ...r, part: 'B2B' })), ...(g1.hsn?.hsn_b2c || []).map((r: Row) => ({ ...r, part: 'B2C' }))]} columns={[{ key: 'part', label: 'Part' }, { key: 'hsn_sc', label: 'HSN/SAC' }, { key: 'desc', label: 'Description' }, { key: 'qty', label: 'Quantity' }, { key: 'rt', label: 'Rate %' }, ...taxColumns]} />
      <Typography variant="body2" color="text.secondary">Documents issued (13): {g1.doc_count?.invoices ?? 0} invoices, {g1.doc_count?.creditNotes ?? 0} credit notes.</Typography>
    </>}
  </Box>;
}

export function ImportExportPage() {
  const [type,setType]=useState('JOURNAL_ENTRIES');const [file,setFile]=useState<File|null>(null);const [busy,setBusy]=useState(false);const [result,setResult]=useState<Row|null>(null);const [error,setError]=useState('');
  const [company,setCompany]=useState('');const [from,setFrom]=useState(()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-01`;});const [to,setTo]=useState(new Date().toISOString().slice(0,10));
  const tally=async(part:'masters'|'vouchers')=>{setError('');try{await download(`${a}/export/tally`,{part,company:company.trim()||undefined,startDate:part==='vouchers'?from:undefined,endDate:part==='vouchers'?to:undefined},part==='masters'?'tally-ledgers.xml':`tally-vouchers-${from}-to-${to}.xml`);}catch(e){setError(String(messageOf(e)));}};
  const upload=async()=>{if(!file)return;const data=new FormData();data.append('file',file);data.append('type',type);setBusy(true);setError('');try{setResult((await api.post(`${a}/import`,data)).data);}catch(e){setError(String(messageOf(e)));}finally{setBusy(false);}};
  return <Box><PageHeading title="Import & export" detail="Upload a tracked CSV import, download the journal ledger, or export to Tally." action={<Button disabled={!hasAccountingPermission("accounting:export")} startIcon={<DownloadRounded/>} variant="outlined" onClick={async()=>{try{const r=await api.get(`${a}/export/ledger`,{responseType:'blob'});const u=URL.createObjectURL(r.data);const link=document.createElement('a');link.href=u;link.download='accounting-ledger.csv';link.click();setTimeout(()=>URL.revokeObjectURL(u),30000);}catch(e){setError(String(messageOf(e)));}}}>Export ledger</Button>}/><Paper variant="outlined" sx={{p:3,maxWidth:720}}><Typography variant="h6" fontWeight={800} sx={{mb:2}}>Upload CSV</Typography><Stack spacing={2}><TextField select label="Import type" value={type} onChange={e=>setType(e.target.value)}>{[['JOURNAL_ENTRIES','Journal entries'],['BANK_STATEMENT','Bank statement lines'],['INVOICES','Invoices']].map(([v,l])=><MenuItem value={v} key={v}>{l}</MenuItem>)}</TextField><Button component="label" variant="outlined">{file?.name||'Choose CSV'}<input hidden type="file" accept=".csv,text/csv" onChange={e=>setFile(e.target.files?.[0]||null)}/></Button><Typography variant="caption" color="text.secondary">Journal columns: entry_key, period_date, description, account_code, debit_amount, credit_amount, currency. Invoice columns: invoice_number, user_id, subtotal, tax_amount, currency, issue_date, due_date.</Typography><Button variant="contained" disabled={!file||busy||!hasAccountingPermission("accounting:import")} onClick={upload}>{busy?'Importing…':'Import CSV'}</Button>{error&&<Alert severity="error">{error}</Alert>}{result&&<Alert severity={result.errorRows?'warning':'success'}>Import {result.status||'finished'}: {result.processedRows}/{result.totalRows} rows processed. {result.errorRows||0} errors. {Array.isArray(result.errors)&&result.errors.slice(0,5).map((x:any)=><div key={x}>{x}</div>)}</Alert>}</Stack></Paper>
    {hasAccountingPermission("accounting:export")&&<Paper variant="outlined" sx={{p:3,maxWidth:720,mt:3}}><Typography variant="h6" fontWeight={800}>Export to Tally</Typography><Typography variant="body2" color="text.secondary" sx={{mb:2}}>Tally XML files in the book currency. In Tally: Gateway of Tally → Import → Masters (ledgers first), then Import → Transactions (vouchers).</Typography><Stack spacing={2}><TextField label="Tally company name (optional)" helperText="Imports into the company open in Tally when empty" value={company} onChange={e=>setCompany(e.target.value)}/><Stack direction={{xs:'column',sm:'row'}} spacing={2}><TextField label="From" type="date" InputLabelProps={{shrink:true}} value={from} onChange={e=>setFrom(e.target.value)}/><TextField label="To" type="date" InputLabelProps={{shrink:true}} value={to} onChange={e=>setTo(e.target.value)}/></Stack><Stack direction="row" spacing={1}><Button variant="outlined" startIcon={<DownloadRounded/>} onClick={()=>void tally('masters')}>1. Ledgers (masters)</Button><Button variant="contained" startIcon={<DownloadRounded/>} disabled={!from||!to||from>to} onClick={()=>void tally('vouchers')}>2. Vouchers</Button></Stack></Stack></Paper>}
  </Box>;
}

export function AccountingAdminApp() {
  const location=useLocation();const navigate=useNavigate();const pathname=location.pathname.replace(/\/$/,'');const base=pathname.startsWith('/accounting')?'/accounting':'';const route=pathname.slice(base.length)||'/';
  const links: [string,string][]=[['/','Overview'],['/invoices','Invoices'],['/journals','Journals'],['/journal-approvals','Journal approvals'],['/accounts','Accounts'],['/periods','Periods'],['/reports','Reports'],['/reconciliation','Reconciliation'],['/gst','GST returns'],['/import-export','Import / export']];
  const visibleLinks=links.filter(([path])=>path==='/periods'
    ? hasAccountingPermission('accounting:write')||hasAccountingPermission('accounting:approve')
    : path==='/import-export'
      ? hasAccountingPermission('accounting:import')||hasAccountingPermission('accounting:export')
      : path==='/journal-approvals'
        ? hasAccountingPermission('accounting:read')||hasAccountingPermission('accounting:write')||hasAccountingPermission('accounting:approve')
      : hasAccountingPermission('accounting:read'));
  const active=visibleLinks.some(([p])=>p===route)?route:'/';
  const routeVisible=visibleLinks.some(([p])=>p===route);
  return <Box sx={{maxWidth:1440,mx:'auto',p:{xs:1,md:3}}}><Paper variant="outlined" sx={{mb:3,borderRadius:3}}><Tabs value={active} onChange={(_,value)=>navigate(`${base}${value==='/'?'':value}`)} variant="scrollable" scrollButtons="auto">{visibleLinks.map(([to,label])=><Tab key={to} value={to} label={label}/>)}</Tabs></Paper>
    {!routeVisible ? <Alert severity="info">Your assigned accounting role does not include this workspace.</Alert> : route==='/invoices'?<InvoicesPage/>:route==='/journals'?<JournalPage/>:route==='/journal-approvals'?<JournalApprovalsPage/>:route==='/accounts'?<ChartOfAccountsPage/>:route==='/periods'?<AccountingPeriodsPage/>:route==='/reports'?<ReportsPage/>:route==='/reconciliation'?<ReconciliationPage/>:route==='/gst'?<GstReturnsPage/>:route==='/import-export'?<ImportExportPage/>:<FinanceOverviewPage/>}
  </Box>;
}
